#ifndef UI_TYPES_H
#define UI_TYPES_H

#include <stdint.h>
#include <stdbool.h>

/* -----------------------------------------------------------------------
 * ui_types.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) added the 28 Oct 2026 demo types (speaker lockout, battery time, fault and debug screens).
 * BJT2 Sound Modulating Toy — Shared UI Types
 * Author: Tony (Display/UI subsystem)
 *
 * All enums, structs, and constants used across the UI subsystem.
 * No HAL or hardware dependencies — pure C definitions only.
 *
 * Design note: this is the single source of truth for all type
 * definitions. Every other module includes this file and nothing else
 * for type information.
 * ----------------------------------------------------------------------- */

/* ===================================================================
 * SCREEN LAYOUT CONSTANTS (best-ui: PORTRAIT 240 x 320)
 * main keeps the 320 x 240 landscape layout. Every screen but Debug is
 * four zones, top to bottom, that meet exactly (asserted below):
 *   y   0..33    power header: battery, TO EMPTY, TO FULL (status_view.c)
 *   y  34..71    title bar: title, HOME button
 *   y  72..293   body: vertical-ui's layout, moved down by 32 px
 *   y 294..319   footer: SD chip, what is playing, effect, MUTE
 * The header and footer are dead to touch (on the fault screen a tap
 * anywhere still closes it). Every screen, element and touch region of
 * main is still there.
 * =================================================================== */

/* Panel rotation = the ILI9341 driver's SCREEN_* ids (tony_ui.c asserts
 * they match), kept as plain numbers so this header stays HAL-free. */
#define UI_ROT_VERTICAL_1       0U  /* MADCTL 0x48 (MX|BGR)       240 x 320 */
#define UI_ROT_HORIZONTAL_1     1U  /* MADCTL 0x28 (MV|BGR)       320 x 240 = main */
#define UI_ROT_VERTICAL_2       2U  /* MADCTL 0x88 (MY|BGR)       240 x 320, VERTICAL_1 turned 180 deg */
#define UI_ROT_HORIZONTAL_2     3U  /* MADCTL 0xE8 (MY|MX|MV|BGR) 320 x 240 */
/* THE switch: the panel (Tony_Init) and the touch (touch_panel_to_screen)
 * both use it. VERTICAL_2 is the right way up on the team's board (checked
 * on the board, 29 Oct 2026). Picture upside down on another board? Change
 * it to UI_ROT_VERTICAL_1: the touch turns with it. */
#define UI_PORTRAIT_ROTATION    UI_ROT_VERTICAL_2

#define SCREEN_W            240U    /* Display width  in pixels (portrait)  */
#define SCREEN_H            320U    /* Display height in pixels (portrait)  */

/* Power header at the top, on every screen but Debug: y 0..33 (drawn by
 * tony_ui.c from status_view.c). No touch region reaches into it. */
#define HEADER_H            34U

/* List rows (Record 2, Effects 6, File 4: Up, Down, Select, Delete): the
 * same boxes as main, they already fit the 240 px width. x 20..219,
 * y 72/104/136/168/200/232 (+30), so the last row ends at y 261. */
#define MENU_X              20U     /* Left edge of all menu items          */
#define MENU_Y0             72U     /* Top edge of first menu item          */
#define MENU_W              200U    /* Width of each menu item              */
#define MENU_H              30U     /* Height of each menu item             */
#define MENU_GAP            32U     /* Spacing from top of one item to next */
#define MENU_ITEM_COUNT     6U      /* Most rows on a screen (Effects)      */

/* Home screen: six tiles in 3 rows x 2 columns (row-major in encoder
 * order: Record, Play / Effects, Volume / File, Battery) filling the
 * body between the title bar and the footer.
 * x 8..115 | 124..231, y 72..137 / 146..211 / 220..285 */
#define HOME_GRID_COLS      2U
#define HOME_GRID_X0        8U
#define HOME_GRID_Y0        72U
#define HOME_CELL_W         108U
#define HOME_CELL_H         66U
#define HOME_CELL_GAP       8U
#define HOME_CELL_X(i)      (HOME_GRID_X0 + ((i) % HOME_GRID_COLS) * (HOME_CELL_W + HOME_CELL_GAP))
#define HOME_CELL_Y(i)      (HOME_GRID_Y0 + ((i) / HOME_GRID_COLS) * (HOME_CELL_H + HOME_CELL_GAP))

/* Volume screen: [ - ] [ + ] [ mute ] side by side under a speaker icon;
 * the value (yellow info line) sits below them.
 * x 12..75 | 88..151 | 164..227, y 144..203 */
#define VOL_BTN_Y           144U
#define VOL_BTN_W           64U
#define VOL_BTN_H           60U
#define VOL_BTN_GAP         12U
#define VOL_BTN_X0          ((SCREEN_W - 3U * VOL_BTN_W - 2U * VOL_BTN_GAP) / 2U)   /* 12 */
#define VOL_BTN_X(i)        (VOL_BTN_X0 + (i) * (VOL_BTN_W + VOL_BTN_GAP))   /* 0 = -, 1 = +, 2 = mute */

/* Dedicated HOME button, right end of the title bar of every screen
 * except Home. Drawn at HOME_BTN_*; the touch target is larger
 * (HOME_HIT_*) so a slightly-off tap near it still counts. The touch box
 * is the title bar's full height: it starts under the header and ends at
 * MENU_Y0, so it never overlaps a menu row.
 * Drawn x 164..235 y 38..65, touch x 152..239 y 34..71. */
#define HOME_BTN_W          72U
#define HOME_BTN_H          28U
#define HOME_BTN_X          (SCREEN_W - HOME_BTN_W - 4U)   /* 164 (main 244) */
#define HOME_BTN_Y          38U
#define HOME_HIT_X          (HOME_BTN_X - 12U)             /* 152 (main 232) */
#define HOME_HIT_Y          HEADER_H                       /* 34 */
#define HOME_HIT_W          (SCREEN_W - HOME_HIT_X)        /* 88 */
#define HOME_HIT_H          38U

/* Play screen: one centred play/pause toggle instead of a list of rows.
 * The touch target extends PLAY_HIT_PAD pixels past the drawn box.
 * 104 x 104: drawn x 68..171 y 88..191, touch x 52..187 y 72..207 */
#define PLAY_BTN_W          104U
#define PLAY_BTN_H          104U
#define PLAY_BTN_X          ((SCREEN_W - PLAY_BTN_W) / 2U) /* 68 */
#define PLAY_BTN_Y          88U
#define PLAY_HIT_PAD        16U

/* Footer at the bottom, the old status bar band (SD chip and two size-1
 * lines, drawn by tony_ui.c from status_view.c): y 294..319. No touch
 * region reaches into it. */
#define STATUS_BAR_H        26U
#define STATUS_BAR_Y        (SCREEN_H - STATUS_BAR_H)      /* 294 */

/* ===================================================================
 * TOUCH CALIBRATION CONSTANTS
 * Raw ADC counts at the edges of the resistive touch panel, measured
 * from the actual hardware — replace if panel is swapped. They belong
 * to the glass, not to the UI rotation, so they are measured in the
 * panel's own LANDSCAPE frame, TOUCH_PANEL_W x TOUCH_PANEL_H (main's
 * picture): the X plate runs along the 320 px side, left -> right, the
 * Y plate along the 240 px side, BOTTOM -> top. touch_calibrate() gives
 * pixels in this frame; touch_panel_to_screen() turns them to the screen.
 * =================================================================== */
#define TOUCH_PANEL_W       320U    /* Panel frame width  (X plate)         */
#define TOUCH_PANEL_H       240U    /* Panel frame height (Y plate)         */
#define TOUCH_X_MIN         365U    /* ADC count at the panel's left   edge */
#define TOUCH_X_MAX         3685U   /* ADC count at the panel's right  edge */
#define TOUCH_Y_MIN         451U    /* ADC count at the panel's BOTTOM edge */
#define TOUCH_Y_MAX         3591U   /* ADC count at the panel's TOP    edge */
                                    /* Y reads inverted: flipped back by    */
                                    /* touch_panel_to_screen()              */

/* ADC values outside this range indicate no finger on panel */
#define TOUCH_NO_PRESS_THRESHOLD_LOW    100U
#define TOUCH_NO_PRESS_THRESHOLD_HIGH   4000U

/* The layout must fit the screen. Nothing else checks it: the touch
 * tables and the renderer use these numbers as they are, so a box past
 * an edge (clipped by the driver) or an unsigned wrap (VOL_BTN_X0 when
 * the buttons are too wide) would only show as a missing or dead button. */
_Static_assert(UI_PORTRAIT_ROTATION == UI_ROT_VERTICAL_1 || UI_PORTRAIT_ROTATION == UI_ROT_VERTICAL_2,
               "vertical-ui needs a portrait rotation");
_Static_assert(SCREEN_W == TOUCH_PANEL_H && SCREEN_H == TOUCH_PANEL_W,
               "portrait UI = touch panel turned 90 deg");
_Static_assert(3U * VOL_BTN_W + 2U * VOL_BTN_GAP <= SCREEN_W,
               "volume buttons too wide (VOL_BTN_X0 would wrap)");
_Static_assert(VOL_BTN_Y >= HOME_HIT_Y + HOME_HIT_H && VOL_BTN_Y + VOL_BTN_H <= STATUS_BAR_Y,
               "volume buttons overlap HOME or status");
_Static_assert(HOME_BTN_X + HOME_BTN_W <= SCREEN_W && HOME_HIT_X <= HOME_BTN_X,
               "HOME button off screen");
_Static_assert(HOME_HIT_Y + HOME_HIT_H <= MENU_Y0,
               "HOME touch box reaches row 0");
_Static_assert(HOME_CELL_X(5U) + HOME_CELL_W <= SCREEN_W && HOME_CELL_Y(5U) + HOME_CELL_H <= STATUS_BAR_Y,
               "Home grid off screen");
_Static_assert(MENU_X + MENU_W <= SCREEN_W &&
               MENU_Y0 + (MENU_ITEM_COUNT - 1U) * MENU_GAP + MENU_H <= STATUS_BAR_Y,
               "menu rows off screen");
_Static_assert(PLAY_BTN_X >= PLAY_HIT_PAD && PLAY_BTN_X + PLAY_BTN_W + PLAY_HIT_PAD <= SCREEN_W,
               "play touch box off screen");
_Static_assert(PLAY_BTN_Y >= HOME_HIT_Y + HOME_HIT_H + PLAY_HIT_PAD &&
               PLAY_BTN_Y + PLAY_BTN_H + PLAY_HIT_PAD <= STATUS_BAR_Y,
               "play touch box hits HOME or status");
/* best-ui: the header, title bar, body and footer meet exactly (the HOME
 * touch box is the title bar's right end), and every touch box starts
 * below the header; the asserts above keep them all above the footer. */
_Static_assert(HOME_HIT_Y == HEADER_H && HOME_HIT_Y + HOME_HIT_H == MENU_Y0 &&
               MENU_Y0 < STATUS_BAR_Y && STATUS_BAR_Y + STATUS_BAR_H == SCREEN_H,
               "header, title bar, body and footer must meet exactly");
_Static_assert(HOME_GRID_Y0 >= HEADER_H && MENU_Y0 >= HEADER_H && VOL_BTN_Y >= HEADER_H &&
               PLAY_BTN_Y >= HEADER_H + PLAY_HIT_PAD,
               "a touch box reaches into the header");
_Static_assert(HOME_BTN_Y >= HOME_HIT_Y && HOME_BTN_Y + HOME_BTN_H <= HOME_HIT_Y + HOME_HIT_H,
               "HOME button drawn outside the title bar");

/* ===================================================================
 * VOLUME CONSTANTS
 * =================================================================== */
#define UI_VOLUME_MIN       0U
#define UI_VOLUME_MAX       100U
#define UI_VOLUME_DEFAULT   50U

/* ===================================================================
 * BATTERY CONSTANTS
 * Millivolt thresholds for a single-cell LiPo battery.
 * Used only by battery_mv_to_pct() (display_logic.c), which the firmware
 * no longer calls: Brendon's fuel gauge reports the charge in % itself
 * (BatteryMsg_t.soc_pct), and that is what the screens show.
 * =================================================================== */
#define BATTERY_MV_MAX      4200U   /* 100% — fully charged LiPo cell      */
#define BATTERY_MV_MIN      3000U   /* 0%   — safe discharge cutoff        */

/* Time to empty / to full from Brendon's battery message, in minutes (his
 * firmware's estimates). This value means "no estimate" (shown as --:--),
 * for example without a valid gauge reading, or the time to full while on
 * battery. Same value as BATMON_TIME_UNKNOWN on his side. */
#define UI_TIME_UNKNOWN     0xFFFFU

/* ui_state_t.prep_pct while no effect file is being made for the file the
 * user waits for (Jack's status is not "preparing"). */
#define UI_PREP_NONE        0xFFU

/* ===================================================================
 * SCREEN IDENTIFIERS
 * Replaces the old flat ui_mode_t enum. The home screen is the root;
 * all other screens are children reached by tapping a home menu item.
 * =================================================================== */
typedef enum {
    UI_SCREEN_HOME = 0,     /* Six-item home menu                          */
    UI_SCREEN_RECORD,       /* Start / stop recording                      */
    UI_SCREEN_PLAY,         /* Play / pause: one toggle button             */
    UI_SCREEN_EFFECTS,      /* Scrollable effect list — select and toggle  */
    UI_SCREEN_VOLUME,       /* Encoder adjusts volume; enc-push = mute     */
    UI_SCREEN_FILE,         /* Scrollable SD file list                     */
    UI_SCREEN_BATTERY,      /* Battery health display                      */
    UI_SCREEN_FAULT,        /* Modal fault overlay: any input dismisses it
                             * and returns to fault_return_screen          */
    UI_SCREEN_DEBUG,        /* Hidden debug screen: hold BACK 2 s on Home.
                             * Five pages, see debug_menu.h                */
    UI_SCREEN_COUNT         /* Sentinel — total number of screens          */
} ui_screen_t;

/* ===================================================================
 * AUDIO EFFECTS
 * One effect active at a time. EFFECT_NONE means bypass.
 * Selecting an active effect toggles it off.
 * Selecting a different effect deactivates the previous one.
 * The names are Tom's (ui_effect_name() in display_logic.c). The same
 * numbers are UiEffect_t in app_rtos.h (tony_ui.c checks the count), which
 * Jack and Tom use: the UI only picks the effect, and Jack plays that
 * effect's file, made ahead of time by FxRenderTask.
 * =================================================================== */
typedef enum {
    EFFECT_NONE = 0,        /* No effect — bypass                          */
    EFFECT_1,               /* Autotune                                    */
    EFFECT_2,               /* Pitch Up                                    */
    EFFECT_3,               /* Pitch Down                                  */
    EFFECT_4,               /* Robot                                       */
    EFFECT_5,               /* Echo                                        */
    EFFECT_6,               /* Reverb                                      */
    EFFECT_COUNT            /* Sentinel — total number of effects          */
} ui_effect_t;

/* ===================================================================
 * PLAYBACK STATE
 * The transport, on every screen: PLAY and REC work from every screen
 * but Fault and Debug, and the footer shows it. tony_ui.c turns each
 * change into a command for Jack (emit_commands).
 * =================================================================== */
typedef enum {
    PLAYBACK_IDLE = 0,      /* Nothing happening                           */
    PLAYBACK_RECORDING,     /* Actively recording to SD card               */
    PLAYBACK_PLAYING,       /* Playing back audio                          */
    PLAYBACK_PAUSED,        /* Playback paused                             */
} playback_state_t;

/* ===================================================================
 * SD CARD STATUS
 * =================================================================== */
typedef enum {
    SD_STATUS_OK = 0,       /* Card present and readable                   */
    SD_STATUS_NO_CARD,      /* No card detected                            */
    SD_STATUS_ERROR,        /* Card present but read/write error           */
} sd_status_t;

/* ===================================================================
 * INPUT EVENTS
 * Everything the UI state machine can receive. Generated by:
 *   - Physical buttons (debounced in firmware)
 *   - Rotary encoder state machine (Module 6); the firmware now counts
 *     the encoder with TIM3 instead (tony_ui.c), giving the same events
 *   - Touch panel pipeline (Modules 2-4)
 * (Module numbers: the module table in PD5b_Tony/README.md.)
 * The state machine itself never reads hardware directly.
 * =================================================================== */
typedef enum {
    /* Global events — handled before screen routing.
     * Work from any screen. Touch and buttons produce the same events —
     * the state machine never knows which input fired. */
    EVENT_GO_HOME = 0,      /* Dedicated Back button — always goes home;
                             * a PAUSED file is stopped on the way         */
    EVENT_BTN_PLAYPAUSE,    /* Play/Pause button — global context-aware:
                             *   IDLE    -> go to Play screen + start
                             *   PLAYING -> pause
                             *   PAUSED  -> resume                         */
    EVENT_BTN_RECORD,       /* Record button — global context-aware:
                             *   IDLE      -> go to Record screen + start
                             *   RECORDING -> stop recording               */
    EVENT_MUTE_TOGGLE,      /* Encoder push — mute toggle, except on Home,
                             * Effects and File, where it selects          */

    /* Home screen navigation — touch tap on a menu item */
    EVENT_NAV_RECORD,           /* Tap "Record"         on home screen     */
    EVENT_NAV_PLAY,             /* Tap "Play"           on home screen     */
    EVENT_NAV_EFFECTS,          /* Tap "Effects"        on home screen     */
    EVENT_NAV_VOLUME,           /* Tap "Volume"         on home screen     */
    EVENT_NAV_FILE,             /* Tap "File"           on home screen     */
    EVENT_NAV_BATTERY,          /* Tap "Battery Status" on home screen     */

    /* Record screen — touch (buttons covered by global events) */
    EVENT_RECORD_START,         /* Tap "Start Recording"                   */
    EVENT_RECORD_STOP,          /* Tap "Stop Recording"                    */

    /* Play screen — touch (buttons covered by global events).
     * No input sends these four any more: the Play screen has one
     * button, which sends EVENT_BTN_PLAYPAUSE (touch_region.c). They
     * stay for the state machine's host tests. */
    EVENT_PLAY_START,           /* Tap "Play"                              */
    EVENT_PLAY_PAUSE,           /* Tap "Pause / Resume" — toggles         */
    EVENT_PLAY_STOP,            /* Tap "Stop"                              */
    EVENT_PLAY_REPLAY,          /* Tap "Replay"                            */

    /* Effects screen — encoder scrolls, enc-push toggles the highlighted
     * effect, a tap on a row picks that row's effect.
     * One effect active at a time. Selecting the active effect
     * toggles it off. Selecting a different effect deactivates
     * the previous one automatically. */
    EVENT_EFFECT_SCROLL_UP,     /* Highlight previous effect (encoder CCW,
                                 * EVENT_VOLUME_DOWN, does the same)       */
    EVENT_EFFECT_SCROLL_DOWN,   /* Highlight next effect (encoder CW,
                                 * EVENT_VOLUME_UP, does the same)         */
    EVENT_EFFECT_SELECT,        /* Toggle highlighted (as the enc-push)    */
    /* Tap on effect row 1..6: highlight that row, then toggle it as
     * SELECT does. Kept in order, one per row (row n = PICK_1 + n), and
     * before EVENT_NONE, so they close a fault screen like every input. */
    EVENT_EFFECT_PICK_1,
    EVENT_EFFECT_PICK_2,
    EVENT_EFFECT_PICK_3,
    EVENT_EFFECT_PICK_4,
    EVENT_EFFECT_PICK_5,
    EVENT_EFFECT_PICK_6,

    /* Volume screen — encoder and touch */
    EVENT_VOLUME_UP,            /* Encoder CW  — one detent                */
    EVENT_VOLUME_DOWN,          /* Encoder CCW — one detent                */

    /* File screen — encoder scroll and touch select */
    EVENT_FILE_SCROLL_UP,       /* Tap "Up" — move selection up (encoder
                                 * CCW, EVENT_VOLUME_DOWN, does the same)  */
    EVENT_FILE_SCROLL_DOWN,     /* Tap "Down" — move selection down
                                 * (encoder CW, EVENT_VOLUME_UP, too)      */
    EVENT_FILE_SELECT,          /* Encoder push or tap — confirm selection */
    EVENT_FILE_DELETE,          /* Tap on row 3 "Delete": the firmware's
                                 * tap-again confirm (delete_confirm.c);
                                 * the state machine changes nothing      */

    /* Fault screen — a touch anywhere on it (buttons and the encoder
     * dismiss it through their own events) */
    EVENT_FAULT_DISMISS,

    /* Sentinels */
    EVENT_NONE,                 /* No event — null return value            */
    EVENT_COUNT                 /* Total event count — do not use directly */
} ui_event_t;

/* ===================================================================
 * FAULTS
 * Mirrors FaultSource_t / FAULT_TEXT_MAX / FAULT_CODE_SIMULATED in
 * Core/Inc/app_rtos.h (the fault message TonyTask receives), so this
 * module stays free of RTOS headers — same idea as ui_effect_t.
 * Keep the numbering identical on both sides.
 * =================================================================== */
#define UI_FAULT_TEXT_MAX       21U     /* 20 characters + NUL per line   */
#define UI_FAULT_CODE_SIMULATED 0x80U   /* set by the debug fault injection */

typedef enum {
    UI_FAULT_SRC_STORAGE = 0,   /* SD card, files                          */
    UI_FAULT_SRC_BATTERY,       /* Fuel gauge, critical charge             */
    UI_FAULT_SRC_USB,           /* USB-MSC hand-over                       */
    UI_FAULT_SRC_AUDIO,         /* Microphone or speaker DMA did not start */
    UI_FAULT_SRC_SYSTEM,        /* Anything else                           */
    UI_FAULT_SRC_COUNT          /* Sentinel                                */
} ui_fault_source_t;

/* ===================================================================
 * ENCODER PIN STATE
 * The two quadrature signal lines from the Bourns PEC12R encoder.
 * Passed into the encoder state machine instead of reading GPIO directly.
 * =================================================================== */
typedef struct {
    bool pin_a;             /* State of encoder channel A                  */
    bool pin_b;             /* State of encoder channel B                  */
} encoder_pins_t;

/* ===================================================================
 * ENCODER STATE MACHINE STATE
 * Tracks position within the quadrature sequence to determine
 * direction and filter out bounce. Opaque to callers — only the
 * encoder module writes to this struct.
 * =================================================================== */
typedef enum {
    ENC_STATE_IDLE = 0,     /* Both pins high — resting between detents    */
    ENC_STATE_CW_1,         /* First step of clockwise sequence            */
    ENC_STATE_CW_2,         /* Second step of clockwise sequence           */
    ENC_STATE_CW_3,         /* Third step — about to fire EVENT_VOLUME_UP  */
    ENC_STATE_CCW_1,        /* First step of counter-clockwise sequence    */
    ENC_STATE_CCW_2,        /* Second step of counter-clockwise sequence   */
    ENC_STATE_CCW_3,        /* Third step — about to fire EVENT_VOLUME_DOWN*/
} encoder_state_t;

typedef struct {
    encoder_state_t state;  /* Current position in quadrature sequence     */
} encoder_sm_t;

/* ===================================================================
 * TOUCH REGION
 * A rectangular area on screen with an associated event.
 * Used by touch_region module to map pixel coordinates to events.
 * =================================================================== */
typedef struct {
    uint16_t    x;          /* Left edge in pixels                         */
    uint16_t    y;          /* Top edge in pixels                          */
    uint16_t    w;          /* Width in pixels                             */
    uint16_t    h;          /* Height in pixels                            */
    ui_event_t  event;      /* Event fired when this region is tapped      */
} touch_region_t;

/* ===================================================================
 * DISPLAY INFO
 * Produced by display_logic module. Describes what should be drawn
 * on screen without making any SPI/HAL calls. Testable on host.
 * =================================================================== */
#define DISPLAY_LABEL_MAX   32U     /* Max characters in any label string  */
#define DISPLAY_FILE_MAX    13U     /* 8.3 filename + null terminator       */

typedef struct {
    ui_screen_t screen;                     /* Which screen is active       */

    /* Labels for the current screen's content */
    char        line1[DISPLAY_LABEL_MAX];   /* Primary info line            */
    char        line2[DISPLAY_LABEL_MAX];   /* Secondary info line          */
    char        line3[DISPLAY_LABEL_MAX];   /* Third info line              */
    char        line4[DISPLAY_LABEL_MAX];   /* Fourth info line             */
    char        line5[DISPLAY_LABEL_MAX];   /* Fifth (Battery screen only)  */
    char        line6[DISPLAY_LABEL_MAX];   /* Sixth (Battery screen only)  */

    /* Persistent status bar items (shown on all screens) */
    uint8_t     battery_pct;               /* 0-100 for icon/bar           */
    bool        muted;                     /* Show mute icon if true        */
    bool        autotune_on;               /* Any effect is on (named when
                                            * Autotune was the only one);
                                            * the firmware does not draw it */

    /* Volume screen specific */
    uint8_t     effective_volume;          /* 0 if muted, else state.volume */

    /* Home screen — which item the encoder cursor is on */
    ui_screen_t home_highlighted;          /* display driver highlights this */

    /* Battery screen specific */
    uint16_t    battery_mv;               /* Raw millivolts for display     */
} display_info_t;

/* ===================================================================
 * CENTRAL UI STATE STRUCT
 * The single shared struct that captures the full UI state.
 * Tony's code writes to this. No other task reads or writes it: TonyTask
 * keeps it (s_ui in tony_ui.c), copies in what the other tasks report
 * (battery, SD card), and turns each change the state machine makes into
 * a message for Jack or Tom (emit_commands).
 * =================================================================== */
typedef struct {
    ui_screen_t         screen;         /* Which screen is currently shown  */
    playback_state_t    playback;       /* Current record/play state        */

    /* Home screen encoder cursor.
     * Tracks which menu item is highlighted for encoder-based navigation.
     * Encoder CW/CCW scrolls this. Encoder push navigates to it.
     * Touch tap bypasses this and navigates directly. */
    ui_screen_t         home_highlighted; /* Which home item is highlighted  */

    /* Effects — one active at a time. */
    ui_effect_t         active_effect;      /* Currently applied effect     */
    ui_effect_t         effect_highlighted; /* Encoder cursor position      */

    uint8_t             volume;         /* Volume level 0-100               */
    bool                muted;          /* Is audio muted                   */
    uint8_t             battery_pct;    /* Last known battery percentage    */
    uint16_t            battery_mv;     /* Last known battery millivolts    */
    /* Battery screen extras. Like the two above they are copied from
     * Brendon's battery message by the firmware glue; ui_process_event
     * never changes them. Both currents are 0 while the reading is not
     * valid; the times are his firmware's estimates, which follow the
     * 2-minute average, already in the steps the screens show. */
    int16_t             battery_ma_now;   /* Current now (last second), mA, < 0 = discharging */
    int16_t             battery_ma_avg;   /* 2-minute average current, mA, < 0 = discharging  */
    uint16_t            battery_tte_min;  /* Time to empty, min, or UI_TIME_UNKNOWN  */
    uint16_t            battery_ttf_min;  /* Time to full, min, or UI_TIME_UNKNOWN   */
    bool                battery_charging; /* Charger says it is charging             */
    bool                battery_valid;    /* Gauge reading valid (gauge found)       */
    /* Power header (status_view.c), also never changed by ui_process_event.
     * low and critical come with the battery message; the other three are
     * the glue's copy of Brendon's 1 Hz power snapshot, all false while
     * there is none or the newest is over 3 s old. */
    bool                battery_low;           /* SOC < 30 % alarm                  */
    bool                battery_critical;      /* SOC < 10 % alarm                  */
    bool                battery_soc_override;  /* Debug-screen SOC override in force */
    bool                battery_ext_power;     /* Charger input power good (USB in)  */
    bool                battery_charger_fault; /* Charger reports a FAULT            */
    sd_status_t         sd_status;      /* Last known SD card status        */
    /* The File screen's selection. uint16_t: Jack lists every playable
     * .WAV on the card, not just 16 (the glue holds 16 names at a time,
     * file_window.c), so 256 files and more must not wrap to 0. */
    uint16_t            file_index;     /* Selected file: its position in Jack's list (0 = first in card order) */
    uint16_t            file_count;     /* Playable files on the SD card, all of them */
    bool                error_active;   /* Uncleared error present          */

    /* Effect files (copied from Jack's status by the firmware glue, never
     * changed by ui_process_event). Effects are made ahead of time into
     * effect files; PLAY with an effect that is not made yet waits for it:
     *   prep_pct  0..100 while Jack makes that file ("Preparing 45%"),
     *             UI_PREP_NONE otherwise;
     *   fx_na     the original plays although an effect is selected (this
     *             file cannot have effects, or the effect engine is
     *             stalled): "Effect: None (n/a)". */
    uint8_t             prep_pct;
    bool                fx_na;

    /* Critical-battery speaker lockout, copied from Brendon's battery
     * message by the firmware glue (never changed by ui_process_event).
     * While set, Tom keeps the speaker silent; volume and mute changes are
     * still stored here and apply again once the lockout is released. */
    bool                speaker_locked;

    /* Fault overlay (UI_SCREEN_FAULT), filled by ui_show_fault().
     * fault_return_screen is where any input takes the user back to. */
    ui_screen_t         fault_return_screen;
    uint8_t             fault_source;   /* ui_fault_source_t               */
    uint8_t             fault_code;     /* producer's code (+ SIMULATED)   */
    char                fault_line2[UI_FAULT_TEXT_MAX];
    char                fault_line3[UI_FAULT_TEXT_MAX];

    /* Hidden debug screen (UI_SCREEN_DEBUG): where the encoder cursor is,
     * as a debug_page_t page and an item on that page (debug_menu.h).
     * ui_enter_debug() puts it on page 0, item 0; the encoder moves it. */
    uint8_t             debug_page;
    uint8_t             debug_item;
} ui_state_t;

#endif /* UI_TYPES_H */
